import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

export default function InteractiveMap() {
  const [hotspots, setHotspots] = useState([]);
  const [selected, setSelected] = useState(null);

  // Load hotspots from public folder
  useEffect(() => {
    fetch(`${process.env.PUBLIC_URL}/hotspots.json`)
      .then((res) => res.json())
      .then(setHotspots)
      .catch((err) => console.error("Failed to load hotspots:", err));
  }, []);

  const handleTap = (id) => {
    setSelected((prev) => (prev === id ? null : id));
  };

  return (
    <div className="relative w-full max-w-screen-sm mx-auto">
      {/* Background Map */}
      <img
        src={`${process.env.PUBLIC_URL}/school-map.png`}
        alt="School Map"
        className="w-full h-auto"
      />

      {/* Hotspot Markers */}
      {hotspots.map((spot) => (
        <div
		  key={spot.id}
		  className="absolute z-30"
		  style={{
			left: `${spot.x}%`,
			top: `${spot.y}%`,
			transform: "translate(-50%, -50%)",
		  }}
		>
          <button onClick={() => handleTap(spot.id)} className="focus:outline-none">
            <img
              src={`${process.env.PUBLIC_URL}/icons/${spot.icon}`}
              alt={spot.name}
              className="w-8 h-8 object-contain rounded-full shadow-md border-2 border-white z-10"
            />
          </button>

          {/* Popup Panel */}
          <AnimatePresence>
            {selected === spot.id && (
              <motion.div
                className="absolute top-10 left-1/2 transform -translate-x-1/2 bg-white p-2 rounded-lg shadow-lg w-44 z-50"
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.8 }}
              >
                <h4 className="font-semibold mb-1">{spot.name}</h4>
                <p className="text-sm text-gray-700 whitespace-pre-line">
                  {spot.description}
                </p>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      ))}
    </div>
  );
}
